#!/usr/bin/env node
const path = require('path');
const fs = require('fs');
const fsp = require('fs/promises');

function findProjectRoot(startPath) {
    let currentPath = startPath;

    // 向上遍历目录直到找到 package.json 或到达根目录
    while (currentPath !== path.parse(currentPath).root) {
        const packagePath = path.join(currentPath, 'package.json');

        if (fs.existsSync(packagePath)) {
            return {
                projectPath: currentPath,
                packageJson: require(packagePath)
            };
        }

        currentPath = path.dirname(currentPath);
    }

    return null;
}


const modulePath = path.join(__dirname, '../');
const AppInfo = findProjectRoot(path.join(modulePath, '../'))

if (AppInfo == null) {
    throw new Error(`调用${modulePath}时,未找到项目根目录,请确保当前目录包含package.json文件`)
}

const AppPath = AppInfo.projectPath


var pPath = path.join(modulePath, 'package.json')
if (!fs.existsSync(pPath)) {
    return
}
const packageJson = fs.readFileSync(pPath, 'utf8');
const package = JSON.parse(packageJson);

// 检查是否存在file-sync或file-sync-overwrite配置
const fileSync = package['file-sync'];
const fileSyncOverwrite = package['file-sync-overwrite'];


// 仅一次
if (fileSync) {
    for (const [key, value] of Object.entries({ ...fileSync })) {
        const sourcePath = path.join(modulePath, key);
        const targetPath = path.join(AppPath, value);
        try {
            if (!fs.existsSync(targetPath)) {
                fs.mkdirSync(path.dirname(targetPath), { recursive: true });
                fsp.cp(sourcePath, targetPath, { recursive: true });
            }
        } catch (e) {
            if (e.code == "ENOENT") {
                throw (`node_modules/${module}/package.json 配置中,'file-sync'节点配置错误,未找到匹配的文件路径 '${key}'`)
            }
            throw (e)
        }
    }
}

// 覆写
if (fileSyncOverwrite) {
    for (const [key, value] of Object.entries({ ...fileSyncOverwrite })) {
        try {
            const sourcePath = path.join(modulePath, key);
            const targetPath = path.join(AppPath, value);

            if (fs.existsSync(targetPath)) {
                fs.rmSync(targetPath, { recursive: true, force: true });
            }

            if (!fs.existsSync(targetPath)) {
                fs.mkdirSync(path.dirname(targetPath), { recursive: true });
                fsp.cp(sourcePath, targetPath, { recursive: true });
            }
        } catch (e) {
            if (e.code == "ENOENT") {
                throw (`node_modules/${module}/package.json 配置中,'file-sync-overwrite'节点配置错误,未找到匹配的文件路径 '${key}'`)
            }
            throw (e)
        }

    }
}
